function publishArtQuickCodePatch (target, bytes, relocatedLength) {
  const api = getApi();
  if (api['art::ThreadList::SuspendAll'] === undefined || api['art::ThreadList::ResumeAll'] === undefined) {
    throw new Error('ART exclusive suspension API unavailable for quick-code publication');
  }
  const size = bytes.byteLength;
  if (size === 0 || (relocatedLength !== undefined && size > relocatedLength)) {
    throw new Error('ART quick-code patch exceeds its completed relocation');
  }
  // Prepare every byte/callback before STW. No writer/literal generation or
  // Java/JNI work runs in the apply callbacks, including failure rollback.
  const previous = target.readByteArray(size);
  const copy = code => code.writeByteArray(bytes);
  const restore = code => code.writeByteArray(previous);
  let failure = null, rollbackFailure = null;
  withAllArtThreadsSuspended(() => {
    try { Memory.patchCode(target, size, copy); }
    catch (error) {
      failure = error;
      try { Memory.patchCode(target, size, restore); }
      catch (error) { rollbackFailure = error; }
    }
  });
  if (failure !== null) {
    if (rollbackFailure !== null) failure.quickCodeRollbackFailure = String(rollbackFailure);
    throw failure;
  }
  return bytes;
}

