    try {
      if (this.publishedCode !== null) {
        const observed = new Uint8Array(this.address.readByteArray(this.publishedCode.byteLength));
        const expected = new Uint8Array(this.publishedCode);
        let owned = observed.length === expected.length;
        for (let i = 0; owned && i < expected.length; i++) owned = observed[i] === expected[i];
        if (!owned) { this.restoreSkipped = true; return; }
